"""Generate a dependency-free interactive Design Lab preview from Experience Core.

The preview is intentionally pattern-specific.  It is not a static screenshot:
controls, states, responsive composition, theme, density, and the core journey
can be exercised before code is applied to a real project.
"""
from __future__ import annotations

import html
import json
from pathlib import Path
from typing import Any, Mapping


def _json(value: Any) -> str:
    return json.dumps(value, ensure_ascii=False).replace("</", "<\\/")


def _data_workbench(entity: str) -> tuple[str, str]:
    body = f'''<div class="page-head"><div><div class="eyebrow">高频记录工作台</div><h2>{html.escape(entity)}查找、比较与处理</h2><p>筛选、选中、详情与下一步保持在同一任务上下文。</p></div><button class="primary" id="newBtn">新建{html.escape(entity)}</button></div>
<div class="metrics"><article><span>待处理</span><b>24</b><small>较昨日 -8%</small></article><article><span>需关注</span><b>3</b><small>优先核对</small></article><article><span>今日完成</span><b>18</b><small>平均 4.2 分钟</small></article><article><span>数据状态</span><b class="small-value">已更新</b><small>2 分钟前</small></article></div>
<div class="workspace split" id="workspace"><section class="panel list-panel"><div class="panel-head"><div class="filters"><input id="search" type="search" placeholder="搜索名称、编号或负责人" aria-label="搜索记录"><select id="filter" aria-label="筛选状态"><option value="">全部状态</option><option>正常</option><option>需关注</option></select><button id="clearBtn">清除</button></div></div><div id="stateArea"></div><div class="record-list" id="recordList"></div></section><section class="panel detail-panel"><div class="panel-head"><button class="mobile-back" id="backBtn">← 返回列表</button><b>详情与下一步</b><span class="status good">对象一致</span></div><div id="detail" class="detail"></div></section></div>'''
    script = f'''const records=[
{{id:'KH-2401',name:'华东设备服务中心',owner:'张明',status:'正常',level:'重点客户',phone:'138****6621',region:'上海',updated:'今天 09:42'}},
{{id:'KH-2398',name:'北方农机合作社',owner:'李娜',status:'需关注',level:'经销商',phone:'139****1048',region:'河北',updated:'昨天 17:18'}},
{{id:'KH-2386',name:'远景工程项目部',owner:'王强',status:'正常',level:'项目客户',phone:'136****8820',region:'江苏',updated:'昨天 14:06'}},
{{id:'KH-2362',name:'新禾农业服务站',owner:'赵云',status:'正常',level:'服务网点',phone:'137****3306',region:'河南',updated:'07-14 16:25'}},
{{id:'KH-2341',name:'西南设备租赁中心',owner:'周敏',status:'需关注',level:'合作伙伴',phone:'135****5732',region:'四川',updated:'07-13 10:11'}}];
let selected=records[0];const listEl=$('recordList'),detailEl=$('detail'),workspace=$('workspace'),search=$('search'),filter=$('filter');
function renderList(){{const q=search.value.trim().toLowerCase(),f=filter.value;const filtered=records.filter(r=>(!q||Object.values(r).join(' ').toLowerCase().includes(q))&&(!f||r.status===f));$('stateArea').innerHTML='';listEl.style.display='grid';listEl.innerHTML=filtered.map(r=>`<button class="record ${{selected.id===r.id?'selected':''}}" data-id="${{r.id}}"><span class="avatar">${{r.name.slice(0,1)}}</span><span><b>${{r.name}}</b><small>${{r.id}} · ${{r.region}}</small></span><span class="secondary"><i class="status ${{r.status==='需关注'?'warn':'good'}}">${{r.status}}</i></span><span class="secondary muted">${{r.owner}}</span></button>`).join('');if(!filtered.length){{listEl.innerHTML='';$('stateArea').innerHTML=stateCard('没有匹配结果','调整关键词或清除筛选。','清除筛选')}}document.querySelectorAll('.record').forEach(b=>b.onclick=()=>transition(()=>{{selected=records.find(r=>r.id===b.dataset.id);renderList();renderDetail();workspace.classList.add('show-detail')}}))}}
function renderDetail(){{detailEl.innerHTML=`<div class="detail-hero"><span class="avatar large">${{selected.name.slice(0,1)}}</span><div><h3>${{selected.name}}</h3><p>${{selected.id}} · ${{selected.level}}</p></div></div><div class="field-grid"><div><span>负责人</span><b>${{selected.owner}}</b></div><div><span>状态</span><b>${{selected.status}}</b></div><div><span>地区</span><b>${{selected.region}}</b></div><div><span>联系方式</span><b>${{selected.phone}}</b></div><div><span>最近更新</span><b>${{selected.updated}}</b></div><div><span>风险说明</span><b>${{selected.status==='需关注'?'资料即将过期':'暂无风险'}}</b></div></div><div class="actions"><button class="danger" id="archiveBtn">归档</button><button id="noteBtn">添加备注</button><button class="primary" id="processBtn">开始处理</button></div>`;$('processBtn').onclick=()=>toast('已进入处理状态，并保留筛选、选中和滚动上下文。');$('noteBtn').onclick=()=>toast('备注编辑已打开（预览不写入真实数据）。');$('archiveBtn').onclick=()=>toast('高风险操作已隔离：需要确认对象、影响和可逆性。')}}
search.oninput=renderList;filter.onchange=renderList;$('clearBtn').onclick=()=>{{search.value='';filter.value='';renderList()}};$('backBtn').onclick=()=>workspace.classList.remove('show-detail');$('newBtn').onclick=()=>toast('新建将进入引导式表单，并支持草稿与错误恢复。');renderList();renderDetail();'''
    return body, script


def _guided_form(entity: str) -> tuple[str, str]:
    body = f'''<div class="page-head"><div><div class="eyebrow">引导式任务表单</div><h2>新建{html.escape(entity)}检查记录</h2><p>分组、即时校验、草稿恢复和提交复核。</p></div><span class="status good" id="draftStatus">草稿已保存</span></div>
<div class="form-layout"><nav class="step-nav panel" aria-label="表单章节"><button class="step active" data-step="0"><b>1</b><span>基本信息<small>对象和日期</small></span></button><button class="step" data-step="1"><b>2</b><span>检查结果<small>状态和说明</small></span></button><button class="step" data-step="2"><b>3</b><span>复核提交<small>确认影响</small></span></button></nav><section class="panel form-panel"><div class="progress"><span id="progressBar"></span></div><form id="demoForm" novalidate><section class="form-step active" data-form-step="0"><h3>基本信息</h3><p class="muted">先确认对象和时间，避免后续记录归属错误。</p><label>设备编号 <input id="deviceId" required placeholder="例如 A-102"><small class="field-help">可扫码或手动输入</small><em class="field-error"></em></label><label>检查日期 <input id="date" type="date" required><em class="field-error"></em></label><label>检查人员 <input value="王强" readonly></label></section><section class="form-step" data-form-step="1"><h3>检查结果</h3><label>运行状态 <select id="result"><option value="">请选择</option><option>正常</option><option>异常</option></select><em class="field-error"></em></label><label>问题说明 <textarea id="notes" rows="5" placeholder="异常时请说明现象、位置和影响"></textarea><small class="field-help">不会因切换步骤而丢失</small></label><label class="check"><input type="checkbox" id="confirmed"> 我已核对现场信息</label></section><section class="form-step" data-form-step="2"><h3>复核提交</h3><div class="review-card" id="reviewCard"></div><div class="notice warn"><b>提交后会进入审核队列</b><p>预览模式不会写入真实业务数据。</p></div></section><div class="form-actions"><button type="button" id="prevBtn">上一步</button><span></span><button type="button" id="saveBtn">保存草稿</button><button type="button" class="primary" id="nextBtn">下一步</button></div></form></section><aside class="panel summary-panel"><h3>填写提示</h3><ul><li>必填错误会靠近字段显示</li><li>保存失败不会清空输入</li><li>离开页面前提示未保存内容</li><li>提交动作与普通保存分离</li></ul><button id="simulateError">模拟保存失败</button></aside></div>'''
    script = '''let step=0,dirty=false;const steps=[...document.querySelectorAll('.form-step')],nav=[...document.querySelectorAll('.step')];function showStep(index){step=Math.max(0,Math.min(2,index));steps.forEach((x,i)=>x.classList.toggle('active',i===step));nav.forEach((x,i)=>x.classList.toggle('active',i===step));$('progressBar').style.width=((step+1)/3*100)+'%';$('prevBtn').disabled=step===0;$('nextBtn').textContent=step===2?'确认提交':'下一步';if(step===2)renderReview()}function validateCurrent(){let ok=true;if(step===0){[['deviceId','请输入设备编号'],['date','请选择检查日期']].forEach(([id,msg])=>{const el=$(id),error=el.parentElement.querySelector('.field-error');error.textContent=el.value?'':msg;ok=ok&&!!el.value})}if(step===1){const result=$('result'),error=result.parentElement.querySelector('.field-error');error.textContent=result.value?'':'请选择运行状态';ok=ok&&!!result.value;if(result.value==='异常'&&!$('notes').value.trim()){toast('异常状态需要补充问题说明');ok=false}}return ok}function renderReview(){$('reviewCard').innerHTML=`<dl><dt>设备编号</dt><dd>${$('deviceId').value||'未填写'}</dd><dt>检查日期</dt><dd>${$('date').value||'未填写'}</dd><dt>运行状态</dt><dd>${$('result').value||'未选择'}</dd><dt>说明</dt><dd>${$('notes').value||'无'}</dd></dl>`}$('nextBtn').onclick=()=>{if(step<2){if(validateCurrent())transition(()=>showStep(step+1));else toast('请先修正当前步骤的错误')}else{if(!$('confirmed').checked){toast('请返回检查结果并确认现场信息');return}toast('提交已被安全拦截：预览仅演示反馈和状态。')}};$('prevBtn').onclick=()=>transition(()=>showStep(step-1));nav.forEach(x=>x.onclick=()=>{const target=Number(x.dataset.step);if(target<=step||validateCurrent())transition(()=>showStep(target))});document.querySelectorAll('input,select,textarea').forEach(x=>x.addEventListener('input',()=>{dirty=true;$('draftStatus').textContent='有未保存修改';$('draftStatus').className='status warn'}));$('saveBtn').onclick=()=>{dirty=false;$('draftStatus').textContent='草稿已保存';$('draftStatus').className='status good';toast('草稿已本地保存，返回后可恢复。')};$('simulateError').onclick=()=>{dirty=true;$('draftStatus').textContent='保存失败，可重试';$('draftStatus').className='status bad';toast('网络失败：输入已保留，可安全重试。')};window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=''}});showStep(0);'''
    return body, script


def _dashboard(_: str) -> tuple[str, str]:
    body = '''<div class="page-head"><div><div class="eyebrow">运营驾驶舱</div><h2>状态、异常与下一项工作</h2><p>不是同权重 KPI 卡片集合，而是面向判断和行动的工作台。</p></div><select id="range" aria-label="时间范围"><option>今天</option><option>本周</option><option>本月</option></select></div><div class="metrics dashboard-metrics"><article class="focus"><span>待处理任务</span><b id="pendingMetric">24</b><small>其中 3 项高风险</small></article><article><span>及时完成率</span><b>92%</b><small>目标 95%</small></article><article><span>平均处理时长</span><b>4.2m</b><small>较昨日 -11%</small></article><article><span>数据新鲜度</span><b class="small-value">2 分钟</b><small id="freshness" aria-live="polite">正常</small></article></div><div class="dashboard-grid"><section class="panel alerts" id="alertsPanel" aria-labelledby="alertsTitle"><div class="panel-head"><b id="alertsTitle">需要立即处理</b><span class="status warn">3 项</span></div><div class="alert-list" id="alertList"></div></section><section class="panel chart-panel" id="trendPanel" aria-labelledby="trendTitle" aria-busy="false"><div class="panel-head"><b id="trendTitle">处理趋势</b><button id="refreshBtn" type="button" aria-controls="trendPanel">局部刷新</button></div><div class="bars" id="bars" role="img" aria-labelledby="trendTitle" aria-describedby="trendDescription"></div><p id="trendDescription" class="muted">按当前时间范围展示每日完成量；可展开数据表查看准确数值。</p><details class="chart-data"><summary>查看趋势数据表</summary><div id="chartTable" aria-live="polite"></div></details><div class="legend"><span><i class="dot brand"></i>完成</span><span><i class="dot muted-dot"></i>待处理</span></div></section><section class="panel tasks" id="tasksPanel" aria-labelledby="tasksTitle"><div class="panel-head"><b id="tasksTitle">今日任务队列</b><button id="sortBtn" type="button">按优先级</button></div><div id="taskRows"></div></section><section class="panel insight"><div class="panel-head"><b>判断摘要</b></div><div class="insight-body"><h3>资料过期是当前主要异常</h3><p>集中在北方区域的 2 个服务网点，建议先分派资料补录任务。</p><button class="primary" id="assignBtn" type="button">创建处理任务</button></div></section></div>'''
    script = '''const alerts=[{title:'客户资料即将过期',meta:'2 个对象 · 北方区域',level:'高'},{title:'处理队列积压',meta:'超过 SLA 30 分钟',level:'中'},{title:'接口数据延迟',meta:'最后更新 18 分钟前',level:'中'}];const tasks=[['补录客户资料','高','张明','今天 16:00'],['核对设备异常','高','李娜','今天 17:30'],['完成周报复核','中','王强','明天 10:00'],['更新服务网点','低','周敏','本周五']];const trendByRange={今天:[14,18,16,22,20,25,24],本周:[78,92,86,104,98,115,121],本月:[310,286,344,328,372,401,418]};const labels=['一','二','三','四','五','六','日'];const rank={高:3,中:2,低:1};let currentRange='今天',selectedAlert=-1,selectedTask=-1,sortMode='priority',refreshTimer=null;function renderChart(data){$('bars').setAttribute('aria-label',currentRange+'趋势图');$('bars').innerHTML=data.map((v,i)=>`<div><span aria-hidden="true" style="height:${Math.max(8,v*5)}px"></span><small>${labels[i]}</small></div>`).join('');$('chartTable').innerHTML=`<table><caption>${currentRange}处理趋势数据</caption><thead><tr><th scope="col">日期</th><th scope="col">完成量</th></tr></thead><tbody>${data.map((v,i)=>`<tr><th scope="row">${labels[i]}</th><td>${v}</td></tr>`).join('')}</tbody></table>`}function render(){const sorted=[...tasks].sort((a,b)=>sortMode==='priority'?(rank[b[1]]-rank[a[1]])||a[3].localeCompare(b[3]):a[3].localeCompare(b[3]));$('alertList').innerHTML=alerts.map((a,i)=>`<button type="button" class="alert-item ${selectedAlert===i?'selected':''}" data-alert="${i}" aria-pressed="${selectedAlert===i?'true':'false'}"><span class="alert-icon" aria-hidden="true">!</span><span><b>${a.title}</b><small>${a.meta}</small></span><i class="status ${a.level==='高'?'bad':'warn'}">${a.level}</i></button>`).join('');$('taskRows').innerHTML=sorted.map((t)=>{const i=tasks.indexOf(t);return `<button type="button" class="task-row ${selectedTask===i?'selected':''}" data-task="${i}" aria-pressed="${selectedTask===i?'true':'false'}"><span><b>${t[0]}</b><small>${t[2]} · ${t[3]}</small></span><i class="status ${t[1]==='高'?'bad':t[1]==='中'?'warn':'good'}">${t[1]}</i></button>`}).join('');$('sortBtn').textContent=sortMode==='priority'?'按截止时间':'按优先级';renderChart(trendByRange[currentRange]||trendByRange.今天)}$('alertList').onclick=e=>{const button=e.target.closest('[data-alert]');if(!button)return;selectedAlert=Number(button.dataset.alert);render();toast('已聚焦异常：'+alerts[selectedAlert].title)};$('taskRows').onclick=e=>{const button=e.target.closest('[data-task]');if(!button)return;selectedTask=Number(button.dataset.task);render();toast('已选中任务：'+tasks[selectedTask][0])};$('range').onchange=e=>{currentRange=e.target.value;$('trendPanel').setAttribute('aria-busy','true');transition(()=>render());$('freshness').textContent='正在更新…';window.clearTimeout(refreshTimer);refreshTimer=window.setTimeout(()=>{$('trendPanel').setAttribute('aria-busy','false');$('freshness').textContent='刚刚更新';toast('时间范围已切换，趋势和任务保持同一口径。')},350)};$('refreshBtn').onclick=()=>{const button=$('refreshBtn');button.disabled=true;$('trendPanel').setAttribute('aria-busy','true');transition(()=>{$('freshness').textContent='正在更新…'});window.clearTimeout(refreshTimer);refreshTimer=window.setTimeout(()=>{render();$('trendPanel').setAttribute('aria-busy','false');$('freshness').textContent='刚刚更新';button.disabled=false;toast('仅刷新受影响区域，页面上下文未丢失。')},700)};$('sortBtn').onclick=()=>{sortMode=sortMode==='priority'?'due':'priority';render();toast(sortMode==='priority'?'任务已按优先级排序。':'任务已按截止时间排序。')};$('assignBtn').onclick=()=>toast('已生成任务草稿，正式分派前需要确认负责人和截止时间。');render();'''
    return body, script


def _mobile_field(entity: str) -> tuple[str, str]:
    body = f'''<div class="field-shell"><div class="field-status"><span id="networkBadge" class="status good">在线</span><span>今日 4 个任务 · 已完成 2 个</span><button id="offlineBtn">模拟弱网</button></div><section class="panel field-card"><div class="task-top"><span class="avatar large">A</span><div><div class="eyebrow">当前任务</div><h2>设备 A-102 现场检查</h2><p>东区 3 号作业点 · 距离 120m</p></div></div><div class="step-strip"><button class="active" data-field-step="0"><b>1</b>识别设备</button><button data-field-step="1"><b>2</b>检查记录</button><button data-field-step="2"><b>3</b>确认完成</button></div><div class="field-step active" data-field-panel="0"><div class="scan-box"><span>⌁</span><h3>扫码或输入设备编号</h3><p>强光环境下保持高对比和大触控。</p><button class="primary" id="scanBtn">扫码识别</button><input id="manualId" placeholder="手动输入编号" value="A-102"></div></div><div class="field-step" data-field-panel="1"><label>运行状态 <select id="fieldResult"><option>正常</option><option>异常</option></select></label><label>现场说明 <textarea id="fieldNotes" rows="4" placeholder="说明检查现象"></textarea></label><button id="photoBtn">＋ 添加现场照片</button><div id="photoState" class="muted">尚未添加照片</div></div><div class="field-step" data-field-panel="2"><div class="review-card"><h3>确认任务结果</h3><dl><dt>设备</dt><dd>A-102</dd><dt>状态</dt><dd id="fieldReviewResult">正常</dd><dt>照片</dt><dd id="fieldReviewPhoto">未添加</dd></dl></div><div class="notice warn"><b>确认后将进入后台同步</b><p>离线时先保存为待同步任务，不会丢失内容。</p></div></div></section><div class="field-bottom"><button id="fieldPrev">上一步</button><button id="draftBtn">保存草稿</button><button class="primary" id="fieldNext">下一步</button></div></div>'''
    script = '''let fieldStep=0,offline=false,photo=false;const fieldPanels=[...document.querySelectorAll('[data-field-panel]')],fieldNav=[...document.querySelectorAll('[data-field-step]')];function showField(i){fieldStep=Math.max(0,Math.min(2,i));fieldPanels.forEach((x,n)=>x.classList.toggle('active',n===fieldStep));fieldNav.forEach((x,n)=>x.classList.toggle('active',n===fieldStep));$('fieldPrev').disabled=fieldStep===0;$('fieldNext').textContent=fieldStep===2?'确认完成':'下一步';if(fieldStep===2){$('fieldReviewResult').textContent=$('fieldResult').value;$('fieldReviewPhoto').textContent=photo?'已添加 1 张':'未添加'}}$('offlineBtn').onclick=()=>{offline=!offline;$('networkBadge').textContent=offline?'弱网/离线':'在线';$('networkBadge').className='status '+(offline?'warn':'good');toast(offline?'已进入弱网模式，草稿和任务状态将本地保留。':'网络已恢复，可继续同步。')};$('scanBtn').onclick=()=>toast('已识别设备 A-102，并验证任务对象一致。');$('photoBtn').onclick=()=>{photo=true;$('photoState').textContent='已添加现场照片 1 张';toast('照片已加入本地任务草稿。')};$('draftBtn').onclick=()=>toast(offline?'草稿已离线保存，恢复网络后自动同步。':'草稿已保存。');$('fieldNext').onclick=()=>{if(fieldStep<2)transition(()=>showField(fieldStep+1));else toast(offline?'任务已保存为待同步，未伪造完成状态。':'完成动作需要真实业务授权，预览已安全拦截。')};$('fieldPrev').onclick=()=>transition(()=>showField(fieldStep-1));fieldNav.forEach(x=>x.onclick=()=>transition(()=>showField(Number(x.dataset.fieldStep))));showField(0);'''
    return body, script


def _ai_workspace(_: str) -> tuple[str, str]:
    body = '''<div class="ai-layout"><aside class="panel session-panel"><div class="panel-head"><b>任务</b><button id="newSession">＋</button></div><button class="session active"><b>客户报告优化</b><small>刚刚</small></button><button class="session"><b>活动素材整理</b><small>昨天</small></button><button class="session"><b>UI 改版建议</b><small>周一</small></button></aside><section class="panel ai-canvas"><div class="panel-head"><div><b>客户报告优化</b><small class="block">模型输出、工具状态和引用分层展示</small></div><span class="status good" id="aiStatus">可用</span></div><div class="conversation" id="conversation"><article class="message user"><b>你</b><p>请根据客户资料生成一份简洁的项目进展摘要。</p></article><article class="message assistant"><b>AI 助手</b><p>我会先核对资料范围，再生成摘要，并明确未验证内容。</p><div class="tool-call"><span>✓</span><div><b>读取项目资料</b><small>12 个文件 · 已完成</small></div></div><p>项目整体按计划推进，当前重点是完成移动端验收和客户培训。以下结论基于已提供资料……</p><button class="citation" data-cite="1">[1] 项目周报</button></article></div><div class="composer"><textarea id="prompt" rows="3" placeholder="描述任务，或粘贴需要处理的内容"></textarea><div><button id="attachBtn">添加文件</button><button id="stopBtn" disabled>停止</button><button class="primary" id="sendBtn">发送</button></div></div></section><aside class="panel evidence-panel"><div class="panel-head"><b>证据与控制</b></div><div class="evidence-body" id="evidenceBody"><h3>引用 [1]</h3><p>项目周报 · 2026-07-15</p><p class="muted">“移动端验收计划于本周完成，客户培训安排在下周。”</p><hr><h3>人工控制</h3><label class="check"><input type="checkbox" checked> 输出前标注未验证信息</label><label class="check"><input type="checkbox" checked> 仅使用批准资料</label><button id="compareVersion">比较版本</button></div></aside></div>'''
    # Keep incoming chunks in a bounded preview buffer and touch the DOM once per
    # animation frame; stopping must cancel both the producer and pending frame.
    script = '''let streaming=false,streamTimer=null,streamFrame=null,renderPending=false,streamIndex=0,streamOutput='';
function cancelScheduledStreamFrame(){if(streamFrame===null)return;if(window.cancelAnimationFrame)window.cancelAnimationFrame(streamFrame);else window.clearTimeout(streamFrame);streamFrame=null;renderPending=false}
function finishStream(){if(!streaming)return;streaming=false;if(streamTimer!==null){clearInterval(streamTimer);streamTimer=null}cancelScheduledStreamFrame();$('aiStatus').textContent='完成';$('aiStatus').className='status good';$('stopBtn').disabled=true;$('sendBtn').disabled=false;const tool=document.querySelector('#streamingMsg .tool-call');if(tool)tool.innerHTML='<span>✓</span><div><b>分析任务并核对证据</b><small>已完成</small></div>';document.querySelector('#streamingMsg')?.removeAttribute('id')}
function renderStreamFrame(){streamFrame=null;renderPending=false;if(!streaming)return;const el=document.querySelector('#streamingMsg .stream-text');if(!el){streaming=false;if(streamTimer!==null){clearInterval(streamTimer);streamTimer=null}return}el.textContent=streamOutput.slice(0,streamIndex);const conversation=$('conversation');conversation.scrollTop=conversation.scrollHeight;if(streamIndex>=streamOutput.length)finishStream()}
function scheduleStreamRender(){if(!streaming||renderPending)return;renderPending=true;streamFrame=window.requestAnimationFrame?window.requestAnimationFrame(renderStreamFrame):window.setTimeout(renderStreamFrame,16)}
function pushStreamChunk(){if(!streaming)return;streamIndex=Math.min(streamOutput.length,streamIndex+4);if(streamIndex>=streamOutput.length&&streamTimer!==null){clearInterval(streamTimer);streamTimer=null}scheduleStreamRender()}
function stopStream(){if(!streaming)return;streaming=false;if(streamTimer!==null){clearInterval(streamTimer);streamTimer=null}cancelScheduledStreamFrame();$('aiStatus').textContent='已停止';$('aiStatus').className='status warn';$('stopBtn').disabled=true;$('sendBtn').disabled=false;const tool=document.querySelector('#streamingMsg .tool-call');if(tool){const status=tool.querySelector('small');if(status)status.textContent='用户已中断，可继续或重试'}document.querySelector('#streamingMsg')?.removeAttribute('id')}
function addMessage(text){if(streaming)return;$('conversation').insertAdjacentHTML('beforeend',`<article class="message user"><b>你</b><p>${escapeHtml(text)}</p></article><article class="message assistant" id="streamingMsg"><b>AI 助手</b><p class="stream-text"></p><div class="tool-call"><span>…</span><div><b>分析任务并核对证据</b><small>工具运行中</small></div></div></article>`);$('conversation').scrollTop=$('conversation').scrollHeight;streamOutput='已收到任务。我会先确认范围和证据，再生成可编辑结果；任何未从资料确认的信息都会单独标记。';streamIndex=0;streaming=true;$('aiStatus').textContent='生成中';$('aiStatus').className='status warn';$('stopBtn').disabled=false;$('sendBtn').disabled=true;streamTimer=window.setInterval(pushStreamChunk,8);pushStreamChunk()}
$('sendBtn').onclick=()=>{const text=$('prompt').value.trim();if(!text){toast('请输入任务描述');return}addMessage(text);$('prompt').value=''};$('stopBtn').onclick=stopStream;$('attachBtn').onclick=()=>toast('文件选择在真实项目中受范围与隐私策略控制。');$('newSession').onclick=()=>toast('新任务已创建，旧任务上下文保持独立。');$('compareVersion').onclick=()=>toast('版本比较将突出内容变化、来源和人工采纳状态。');document.querySelectorAll('.citation').forEach(x=>x.onclick=()=>toast('已定位引用 [1]，来源与生成内容保持可追溯。'));'''
    return body, script


def _review_approval(entity: str) -> tuple[str, str]:
    body = f'''<div class="page-head"><div><div class="eyebrow">审核与批准工作台</div><h2>{html.escape(entity)}待审队列</h2><p>证据、风险、历史意见和决定保持在同一上下文。</p></div><div class="actions"><button id="bulkBtn">批量规则</button><button class="primary" id="nextApproval">处理下一项</button></div></div>
<div class="metrics"><article><span>待审核</span><b>18</b><small>3 项临近超时</small></article><article><span>高风险</span><b>4</b><small>必须二次核对</small></article><article><span>今日完成</span><b>31</b><small>平均 2.8 分钟</small></article><article><span>一致率</span><b>94%</b><small>规则与人工结果</small></article></div>
<div class="approval-layout" id="approvalWorkspace"><section class="panel approval-queue"><div class="panel-head"><b>审核队列</b><select id="approvalFilter"><option value="">全部风险</option><option>高风险</option><option>普通</option></select></div><div id="approvalQueue"></div></section><section class="panel approval-detail"><div class="panel-head"><button class="mobile-back" id="approvalBack">← 返回队列</button><b>证据与决定</b><span class="status warn" id="approvalStatus">待决定</span></div><div class="approval-evidence" id="approvalEvidence"></div><label>审核意见<textarea id="approvalNote" rows="4" placeholder="说明批准、退回或拒绝依据"></textarea></label><div class="actions approval-actions"><button class="danger" id="rejectBtn">拒绝</button><button id="returnBtn">退回补充</button><button class="primary" id="approveBtn">批准</button></div></section><aside class="panel approval-history"><div class="panel-head"><b>历史与规则</b></div><div class="approval-history-body"><p><b>规则命中</b></p><ul><li>对象资料完整</li><li>金额超过人工复核阈值</li><li>过去 30 天无重复提交</li></ul><hr><p><b>最近意见</b></p><p class="muted">“合同附件缺少签章页，已于昨日补齐。”</p></div></aside></div>'''
    script = '''const approvals=[{id:'SP-1042',name:'华东服务中心采购申请',risk:'高风险',amount:'¥128,000',owner:'张明',reason:'金额超过自动批准阈值',evidence:['合同附件 4 份','预算余额充足','供应商资质有效']},{id:'SP-1038',name:'设备维修费用确认',risk:'普通',amount:'¥8,600',owner:'李娜',reason:'标准维修项目',evidence:['维修单已签字','报价在目录价内']},{id:'SP-1031',name:'渠道返点调整',risk:'高风险',amount:'¥42,000',owner:'王强',reason:'返点比例发生变化',evidence:['区域经理已确认','财务测算已附'] }];let currentApproval=approvals[0];function renderApprovalQueue(){const f=$('approvalFilter').value;const rows=approvals.filter(x=>!f||x.risk===f);$('approvalQueue').innerHTML=rows.map(x=>`<button class="queue-item ${currentApproval.id===x.id?'active':''}" data-id="${x.id}"><span><b>${x.name}</b><small>${x.id} · ${x.owner}</small></span><span><i class="status ${x.risk==='高风险'?'bad':'good'}">${x.risk}</i><small>${x.amount}</small></span></button>`).join('')||stateCard('暂无待审项','调整风险筛选或稍后重试。','清除筛选');document.querySelectorAll('.queue-item').forEach(x=>x.onclick=()=>transition(()=>{currentApproval=approvals.find(a=>a.id===x.dataset.id);renderApprovalQueue();renderApprovalDetail();$('approvalWorkspace').classList.add('show-detail')}))}function renderApprovalDetail(){$('approvalStatus').textContent='待决定';$('approvalStatus').className='status warn';$('approvalNote').value='';$('approvalEvidence').innerHTML=`<div class="detail-hero"><span class="avatar large">审</span><div><h3>${currentApproval.name}</h3><p>${currentApproval.id} · ${currentApproval.amount}</p></div></div><div class="field-grid"><div><span>申请人</span><b>${currentApproval.owner}</b></div><div><span>风险</span><b>${currentApproval.risk}</b></div><div><span>触发原因</span><b>${currentApproval.reason}</b></div><div><span>材料数量</span><b>${currentApproval.evidence.length} 项</b></div></div><h3>证据清单</h3><ul class="evidence-list">${currentApproval.evidence.map(e=>`<li>✓ ${e}</li>`).join('')}</ul>`}function decide(kind){if(!$('approvalNote').value.trim()&&kind!=='批准'){toast('退回或拒绝必须填写明确理由');$('approvalNote').focus();return}$('approvalStatus').textContent=kind+'完成';$('approvalStatus').className=kind==='批准'?'status good':'status bad';toast(kind+'结果已记录；预览不会写入真实业务。')}$('approvalFilter').onchange=renderApprovalQueue;$('approveBtn').onclick=()=>decide('批准');$('returnBtn').onclick=()=>decide('退回');$('rejectBtn').onclick=()=>decide('拒绝');$('approvalBack').onclick=()=>$('approvalWorkspace').classList.remove('show-detail');$('nextApproval').onclick=()=>{const i=(approvals.indexOf(currentApproval)+1)%approvals.length;currentApproval=approvals[i];renderApprovalQueue();renderApprovalDetail();toast('已切换到下一项，并保留筛选条件。')};$('bulkBtn').onclick=()=>toast('批量操作仅适用于低风险且规则完全一致的项目。');renderApprovalQueue();renderApprovalDetail();'''
    return body, script


def _settings_center(entity: str) -> tuple[str, str]:
    body = f'''<div class="page-head"><div><div class="eyebrow">设置中心</div><h2>{html.escape(entity)}配置</h2><p>分类导航、即时预览、依赖提示和可恢复保存。</p></div><span class="status good" id="settingsStatus">已保存</span></div>
<div class="settings-layout"><aside class="panel settings-nav"><input id="settingsSearch" type="search" placeholder="搜索设置" aria-label="搜索设置"><button class="settings-tab active" data-section="appearance">外观与密度</button><button class="settings-tab" data-section="notifications">通知</button><button class="settings-tab" data-section="workflow">工作流</button><button class="settings-tab" data-section="advanced">高级设置</button></aside><section class="panel settings-content" id="settingsContent"><div class="panel-head"><b id="settingsTitle">外观与密度</b><button id="resetSection">恢复本组默认</button></div><div id="settingsFields"></div><div class="form-actions"><button id="discardSettings">放弃修改</button><span></span><button class="primary" id="saveSettings">保存设置</button></div></section><aside class="panel settings-preview"><div class="panel-head"><b>即时预览</b></div><div class="mini-app" id="settingsPreview"><div class="mini-head">客户工作台</div><div class="mini-card"><b>待处理任务</b><span>12</span></div><div class="mini-list"><i></i><i></i><i></i></div></div><div class="notice"><b>影响范围</b><p id="impactText">仅影响当前用户的显示密度与主题。</p></div></aside></div>'''
    script = '''const settingSections={appearance:{title:'外观与密度',impact:'仅影响当前用户的显示密度与主题。',fields:`<label>主题<select id="themeSetting"><option>跟随系统</option><option>浅色</option><option>深色</option></select></label><label>信息密度<input id="densityRange" type="range" min="1" max="3" value="2"><small class="field-help">紧凑、舒适或触控友好</small></label><label class="check"><input id="reduceMotion" type="checkbox"> 减少动态效果</label>`},notifications:{title:'通知',impact:'改变任务、风险和系统消息的触达方式。',fields:`<label class="check"><input type="checkbox" checked> 关键风险即时通知</label><label class="check"><input type="checkbox" checked> 每日任务摘要</label><label>免打扰时段<input type="text" value="22:00 - 08:00"></label>`},workflow:{title:'工作流',impact:'影响新任务默认分配与超时提醒，不改变历史记录。',fields:`<label>默认负责人<select><option>按区域自动分配</option><option>手动选择</option></select></label><label>超时提醒<input type="number" value="24" min="1"><small class="field-help">单位：小时</small></label><label class="check"><input type="checkbox"> 低风险任务允许自动流转</label>`},advanced:{title:'高级设置',impact:'高级选项可能影响整个团队，保存前需要管理员确认。',fields:`<div class="notice warn"><b>管理员设置</b><p>修改后会影响整个组织。</p></div><label>数据保留期<select><option>180 天</option><option>365 天</option></select></label><label class="check"><input type="checkbox"> 启用实验性交互</label>`}};let section='appearance',dirtySettings=false;function renderSettings(){const s=settingSections[section];$('settingsTitle').textContent=s.title;$('settingsFields').innerHTML=s.fields;$('impactText').textContent=s.impact;document.querySelectorAll('.settings-tab').forEach(x=>x.classList.toggle('active',x.dataset.section===section));$('settingsFields').querySelectorAll('input,select').forEach(x=>x.oninput=markDirty);const d=$('densityRange');if(d)d.oninput=()=>{markDirty();$('settingsPreview').style.setProperty('--mini-gap',[6,10,15][Number(d.value)-1]+'px')};const t=$('themeSetting');if(t)t.onchange=()=>{markDirty();$('settingsPreview').classList.toggle('dark',t.value==='深色')}}function markDirty(){dirtySettings=true;$('settingsStatus').textContent='有未保存修改';$('settingsStatus').className='status warn'}document.querySelectorAll('.settings-tab').forEach(x=>x.onclick=()=>{if(dirtySettings&&!confirm('当前修改尚未保存，仍要切换吗？'))return;section=x.dataset.section;dirtySettings=false;renderSettings()});$('saveSettings').onclick=()=>{dirtySettings=false;$('settingsStatus').textContent='已保存';$('settingsStatus').className='status good';toast('设置已保存，并记录影响范围。')};$('discardSettings').onclick=()=>{dirtySettings=false;renderSettings();$('settingsStatus').textContent='已恢复';$('settingsStatus').className='status good'};$('resetSection').onclick=()=>{markDirty();renderSettings();toast('本组已恢复默认，保存后生效。')};$('settingsSearch').oninput=e=>{const q=e.target.value.trim();document.querySelectorAll('.settings-tab').forEach(x=>x.hidden=!!q&&!x.textContent.includes(q))};window.addEventListener('beforeunload',e=>{if(dirtySettings){e.preventDefault();e.returnValue=''}});renderSettings();'''
    return body, script


def _upload_processing(entity: str) -> tuple[str, str]:
    body = f'''<div class="page-head"><div><div class="eyebrow">上传与处理队列</div><h2>{html.escape(entity)}批量导入</h2><p>上传、校验、处理、失败恢复和结果交付在同一队列中。</p></div><button id="pauseAll">暂停全部</button></div>
<section class="panel upload-zone" id="uploadZone" tabindex="0"><input id="fileInput" type="file" multiple hidden><div class="upload-icon">⇧</div><h3>拖入文件，或选择文件</h3><p class="muted">支持 PDF、图片和表格；预览不会上传真实文件。</p><button class="primary" id="chooseFiles">选择文件</button></section><div class="upload-layout"><section class="panel upload-main"><div class="panel-head"><b>处理队列</b><div><select id="uploadFilter"><option value="">全部状态</option><option>处理中</option><option>失败</option><option>完成</option></select><button id="retryFailed">重试失败项</button></div></div><div id="uploadQueue"></div></section><aside class="panel upload-summary"><div class="panel-head"><b>本批结果</b></div><div class="metrics vertical"><article><span>文件</span><b id="fileCount">4</b></article><article><span>成功</span><b id="successCount">2</b></article><article><span>失败</span><b id="failCount">1</b></article></div><div class="notice warn"><b>部分失败不影响成功项</b><p>失败文件保留原因、原始输入和单独重试入口。</p></div><button class="primary" id="deliverBtn">查看成功结果</button></aside></div>'''
    script = '''let uploads=[{id:1,name:'客户清单.xlsx',size:'1.4 MB',status:'完成',progress:100,note:'128 条记录'},{id:2,name:'合同附件.pdf',size:'4.2 MB',status:'处理中',progress:62,note:'正在提取内容'},{id:3,name:'现场照片.zip',size:'18.7 MB',status:'失败',progress:38,note:'包含不支持的文件'},{id:4,name:'补充说明.docx',size:'720 KB',status:'完成',progress:100,note:'已关联项目'}],paused=false;function renderUploads(){const f=$('uploadFilter').value;const rows=uploads.filter(x=>!f||x.status===f);$('uploadQueue').innerHTML=rows.map(x=>`<article class="upload-item"><span class="file-type">${x.name.split('.').pop().toUpperCase()}</span><div><b>${x.name}</b><small>${x.size} · ${x.note}</small><div class="progress-line"><i style="width:${x.progress}%"></i></div></div><span><i class="status ${x.status==='完成'?'good':x.status==='失败'?'bad':'warn'}">${x.status}</i>${x.status==='失败'?`<button class="retry-one" data-id="${x.id}">重试</button>`:''}</span></article>`).join('')||stateCard('没有匹配文件','调整状态筛选查看其他项目。','查看全部');$('fileCount').textContent=uploads.length;$('successCount').textContent=uploads.filter(x=>x.status==='完成').length;$('failCount').textContent=uploads.filter(x=>x.status==='失败').length;document.querySelectorAll('.retry-one').forEach(x=>x.onclick=()=>retryOne(Number(x.dataset.id)))}function retryOne(id){const item=uploads.find(x=>x.id===id);item.status='处理中';item.progress=45;item.note='已清除不支持文件，重新校验';renderUploads();toast('仅重试失败项，成功结果保持不变。')}function addMockFiles(count=2){for(let i=0;i<count;i++)uploads.unshift({id:Date.now()+i,name:`新增文件-${i+1}.pdf`,size:'1.0 MB',status:'处理中',progress:12,note:'排队等待校验'});renderUploads();toast('文件已进入本地预览队列。')}$('chooseFiles').onclick=()=>$('fileInput').click();$('fileInput').onchange=e=>addMockFiles(e.target.files.length||1);$('uploadZone').ondragover=e=>{e.preventDefault();$('uploadZone').classList.add('dragging')};$('uploadZone').ondragleave=()=>$('uploadZone').classList.remove('dragging');$('uploadZone').ondrop=e=>{e.preventDefault();$('uploadZone').classList.remove('dragging');addMockFiles(e.dataTransfer.files.length||1)};$('retryFailed').onclick=()=>{uploads.filter(x=>x.status==='失败').forEach(x=>{x.status='处理中';x.progress=40;x.note='批量重试中'});renderUploads()};$('pauseAll').onclick=()=>{paused=!paused;$('pauseAll').textContent=paused?'继续全部':'暂停全部';uploads.filter(x=>x.status==='处理中').forEach(x=>x.note=paused?'已暂停，可继续':'继续处理');renderUploads()};$('uploadFilter').onchange=renderUploads;$('deliverBtn').onclick=()=>toast('仅展示成功结果；失败项继续保留在队列中。');renderUploads();'''
    return body, script


def _message_center(entity: str) -> tuple[str, str]:
    body = f'''<div class="page-head"><div><div class="eyebrow">消息与上下文中心</div><h2>{html.escape(entity)}消息</h2><p>按优先级处理消息，并能直接返回对应业务对象。</p></div><button id="markAll">全部标为已读</button></div>
<div class="message-layout" id="messageWorkspace"><section class="panel message-list-panel"><div class="panel-head"><div class="filters"><input id="messageSearch" type="search" placeholder="搜索消息"><select id="messageFilter"><option value="">全部</option><option value="unread">未读</option><option value="risk">风险</option></select></div></div><div id="messageList"></div></section><section class="panel message-detail-panel"><div class="panel-head"><button class="mobile-back" id="messageBack">← 返回消息</button><b>消息详情</b><button id="muteThread">免打扰</button></div><div id="messageDetail" class="message-detail"></div></section></div>'''
    script = '''const messages=[{id:1,title:'客户资料即将过期',summary:'华东服务中心的资质将在 3 天后过期',type:'risk',unread:true,time:'10:24',object:'客户 KH-2401',action:'查看客户资料'},{id:2,title:'审批已通过',summary:'设备维修费用已由财务批准',type:'normal',unread:true,time:'09:16',object:'审批 SP-1038',action:'查看审批记录'},{id:3,title:'上传处理完成',summary:'客户清单已成功导入 128 条记录',type:'normal',unread:false,time:'昨天',object:'导入任务 UP-286',action:'查看导入结果'},{id:4,title:'任务被退回',summary:'现场检查记录需要补充设备照片',type:'risk',unread:false,time:'周二',object:'任务 TK-392',action:'继续补充'}];let selectedMessage=messages[0];function renderMessageList(){const q=$('messageSearch').value.trim(),f=$('messageFilter').value;const rows=messages.filter(x=>(!q||(x.title+x.summary+x.object).includes(q))&&(!f||(f==='unread'?x.unread:x.type==='risk')));$('messageList').innerHTML=rows.map(x=>`<button class="message-row ${selectedMessage.id===x.id?'active':''} ${x.unread?'unread':''}" data-id="${x.id}"><span class="message-dot ${x.type}"></span><span><b>${x.title}</b><small>${x.summary}</small></span><time>${x.time}</time></button>`).join('')||stateCard('没有匹配消息','调整搜索或筛选条件。','清除筛选');document.querySelectorAll('.message-row').forEach(x=>x.onclick=()=>transition(()=>{selectedMessage=messages.find(m=>m.id===Number(x.dataset.id));selectedMessage.unread=false;renderMessageList();renderMessageDetail();$('messageWorkspace').classList.add('show-detail')}))}function renderMessageDetail(){$('messageDetail').innerHTML=`<div class="detail-hero"><span class="avatar large">信</span><div><h3>${selectedMessage.title}</h3><p>${selectedMessage.time} · ${selectedMessage.object}</p></div></div><p class="message-copy">${selectedMessage.summary}。系统已保留触发原因、对象和后续操作，避免消息成为无上下文通知。</p><div class="notice"><b>关联对象</b><p>${selectedMessage.object}</p></div><div class="actions"><button id="archiveMessage">归档消息</button><button class="primary" id="openObject">${selectedMessage.action}</button></div>`;$('openObject').onclick=()=>toast('已进入关联对象，并保留消息筛选与阅读位置。');$('archiveMessage').onclick=()=>toast('消息已归档，可在历史中恢复。')}$('messageSearch').oninput=renderMessageList;$('messageFilter').onchange=renderMessageList;$('markAll').onclick=()=>{messages.forEach(x=>x.unread=false);renderMessageList();toast('已标记全部为已读。')};$('messageBack').onclick=()=>$('messageWorkspace').classList.remove('show-detail');$('muteThread').onclick=()=>toast('仅静音同类低优先级消息，风险消息仍保留。');renderMessageList();renderMessageDetail();'''
    return body, script


def _task_center(entity: str) -> tuple[str, str]:
    body = f'''<div class="page-head"><div><div class="eyebrow">任务中心</div><h2>{html.escape(entity)}工作队列</h2><p>按优先级、时限和阻塞原因组织下一项工作。</p></div><button class="primary" id="claimNext">领取下一项</button></div>
<div class="task-summary"><button class="active" data-task-filter="">全部 <b>18</b></button><button data-task-filter="today">今日到期 <b>6</b></button><button data-task-filter="blocked">被阻塞 <b>3</b></button><button data-task-filter="mine">我的任务 <b>8</b></button></div><div class="task-board"><section class="panel task-queue-panel"><div class="panel-head"><div class="filters"><input id="taskSearch" type="search" placeholder="搜索任务"><select id="taskSort"><option>按优先级</option><option>按到期时间</option></select></div></div><div id="taskQueue"></div></section><aside class="panel task-focus"><div class="panel-head"><b>当前任务</b><span class="status warn" id="taskState">待处理</span></div><div id="taskFocusBody"></div><label>处理备注<textarea id="taskNote" rows="4" placeholder="记录进展或阻塞原因"></textarea></label><div class="actions"><button id="blockTask">标记阻塞</button><button id="saveTask">保存进展</button><button class="primary" id="completeTask">完成任务</button></div></aside></div>'''
    script = '''const tasks=[{id:'TK-401',title:'核对客户资质',priority:3,due:'今天 14:00',owner:'我',status:'today',context:'客户 KH-2401',steps:['核对营业执照','确认有效期','记录风险']},{id:'TK-398',title:'补充现场检查照片',priority:2,due:'今天 17:30',owner:'李娜',status:'blocked',context:'检查单 IN-882',steps:['联系现场人员','上传照片','重新提交']},{id:'TK-392',title:'确认设备维修结果',priority:2,due:'明天 10:00',owner:'我',status:'mine',context:'工单 WO-293',steps:['查看维修记录','联系客户','确认关闭']},{id:'TK-386',title:'整理周度运营摘要',priority:1,due:'周五',owner:'王强',status:'mine',context:'运营周报',steps:['核对指标','补充异常','提交负责人']}];let currentTask=tasks[0],taskFilter='';function renderTasks(){const q=$('taskSearch').value.trim();const rows=tasks.filter(x=>(!q||(x.title+x.context).includes(q))&&(!taskFilter||(taskFilter==='mine'?x.owner==='我':x.status===taskFilter)));$('taskQueue').innerHTML=rows.map(x=>`<button class="task-card ${currentTask.id===x.id?'active':''}" data-id="${x.id}"><i class="priority p${x.priority}">${x.priority}</i><span><b>${x.title}</b><small>${x.context} · ${x.owner}</small></span><span><small>${x.due}</small><i class="status ${x.status==='blocked'?'bad':x.status==='today'?'warn':'good'}">${x.status==='blocked'?'阻塞':x.status==='today'?'今日':'进行中'}</i></span></button>`).join('')||stateCard('当前没有任务','可以调整筛选，或领取下一项工作。','领取任务');document.querySelectorAll('.task-card').forEach(x=>x.onclick=()=>{currentTask=tasks.find(t=>t.id===x.dataset.id);renderTasks();renderTaskFocus()});}function renderTaskFocus(){$('taskState').textContent=currentTask.status==='blocked'?'已阻塞':'待处理';$('taskState').className=currentTask.status==='blocked'?'status bad':'status warn';$('taskNote').value='';$('taskFocusBody').innerHTML=`<h3>${currentTask.title}</h3><p class="muted">${currentTask.id} · ${currentTask.context} · ${currentTask.due}</p><ol class="checklist">${currentTask.steps.map((s,i)=>`<li><label class="check"><input type="checkbox" data-index="${i}"> ${s}</label></li>`).join('')}</ol>`}document.querySelectorAll('[data-task-filter]').forEach(x=>x.onclick=()=>{taskFilter=x.dataset.taskFilter;document.querySelectorAll('[data-task-filter]').forEach(b=>b.classList.toggle('active',b===x));renderTasks()});$('taskSearch').oninput=renderTasks;$('taskSort').onchange=()=>{tasks.sort((a,b)=>$('taskSort').selectedIndex===0?b.priority-a.priority:a.due.localeCompare(b.due));renderTasks()};$('saveTask').onclick=()=>toast('进展已保存，返回后恢复勾选和备注。');$('blockTask').onclick=()=>{if(!$('taskNote').value.trim()){toast('请填写阻塞原因和需要谁协助');$('taskNote').focus();return}currentTask.status='blocked';renderTasks();renderTaskFocus();toast('任务已标记阻塞，并通知相关负责人。')};$('completeTask').onclick=()=>{const checks=[...document.querySelectorAll('#taskFocusBody input')];if(checks.some(x=>!x.checked)){toast('请先完成或明确跳过所有步骤');return}$('taskState').textContent='已完成';$('taskState').className='status good';toast('任务完成，下一项任务已准备。')};$('claimNext').onclick=()=>toast('已领取最高优先级且未被占用的任务。');renderTasks();renderTaskFocus();'''
    return body, script


